for(const [fid,f]of Object.entries(plan.floors)){for(const d of f.doors||[]){if(d.kind==='window'||d.sealed||d.cemented)continue;const a=f.rooms.find(r=>r.id===d.a),b=f.rooms.find(r=>r.id===d.b);if(!a||!b||a.localSteps||b.localSteps||a.stairTransition||b.stairTransition)continue;const difference=Math.abs((a.z??f.z)-(b.z??f.z));if(difference>.2)issues.push({kind:'height',floors:[fid],rooms:[a.id,b.id],text:`Door threshold between ${a.name} and ${b.name}: ${difference.toFixed(2)} m level change; connect these surfaces with local steps`});}}
const ground=0;
for(const [fid,f]of Object.entries(plan.floors)){if(!Number.isFinite(plan.siteGroundZ))continue;const external=[...(f.doors||[]).filter(d=>d.b==='outside'||d.a==='outside').map(d=>({...d,room:d.a==='outside'?d.b:d.a})),...(f.externals||[f.external].filter(Boolean))];for(const d of external){if(d.kind==='window'||d.sealed||d.cemented)continue;const r=f.rooms.find(r=>r.id===d.room);if(!r||r.localSteps||r.stairTransition)continue;const delta=Math.abs((r.z??f.z)-ground);if(delta>.2)issues.push({kind:'height',floors:[fid],rooms:[r.id],text:`Outside entrance at ${r.name}: ${delta.toFixed(2)} m above/below outside ground; check that local steps meet this entrance`});}}
